/* Advanced2 — account isolation, inherited ceilings and explicit grant paths. */
(function(){
 const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x));
 const ROOT='r-shop',W='ou-shop-00000001',PROD='ou-shop-00000002',SEC='ou-shop-00000003',SAND='ou-shop-00000004',MGMT='111111111111',DEV='444444444444',AUDIT='666666666666',SERVICE='config-multiaccountsetup.amazonaws.com';
 const canonical=(v,k='')=>{if(['Action','NotAction','Resource','NotResource','aws:RequestedRegion','s3:LocationConstraint'].includes(k)&&(typeof v==='string'||Array.isArray(v)&&v.every(x=>typeof x==='string')))return (Array.isArray(v)?v:[v]).slice().sort();if(Array.isArray(v)){const a=v.map(x=>canonical(x));if(a.every(x=>x&&typeof x.Sid==='string'))a.sort((a,b)=>a.Sid.localeCompare(b.Sid));return a;}return v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k],k)])):v;};
 const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
 const FULL={Version:'2012-10-17',Statement:[{Effect:'Allow',Action:'*',Resource:'*'}]};
 const REGION={Version:'2012-10-17',Statement:[{Sid:'ScopedRegionalAPIs',Effect:'Deny',Action:['ec2:*','rds:*','s3:CreateBucket'],Resource:'*',Condition:{StringNotEquals:{'aws:RequestedRegion':'ap-south-1'}}},{Sid:'BucketLocation',Effect:'Deny',Action:'s3:CreateBucket',Resource:'*',Condition:{StringNotEquals:{'s3:LocationConstraint':'ap-south-1'}}}]};
 const PROTECT={Version:'2012-10-17',Statement:[{Sid:'ProtectTrail',Effect:'Deny',Action:['cloudtrail:StopLogging','cloudtrail:DeleteTrail'],Resource:'*'}]};
 const IDENTITY={Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:CreateBucket','s3:PutObject','cloudtrail:StopLogging'],Resource:'*'}]};
 const files={'region.json':{desc:'Review kiya scoped EC2/RDS/S3CreateBucket endpoint aur bucket-location ki limit; global services par poori rok nahi',content:JSON.stringify(REGION,null,2)},'audit.json':{desc:'Member identity ke StopLogging/DeleteTrail par review ki limit; SLR/management ke exceptions phir bhi hain',content:JSON.stringify(PROTECT,null,2)},'identity.json':{desc:'Pehle se bana, review kiya sandbox role grant; SCP yeh grant nahi banata',content:JSON.stringify(IDENTITY,null,2)}};
 const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
 function seed(sandbox=false,broken=false){
  const units=[{id:W,name:'Workloads',parentId:ROOT,fixtureId:'original-workloads'},{id:PROD,name:'Production',parentId:W,fixtureId:'original-prod'},{id:SEC,name:'Security',parentId:ROOT,fixtureId:'original-security'},...(sandbox?[{id:SAND,name:'Sandbox',parentId:W,fixtureId:'original-sandbox'}]:[])];
  const accounts=[[MGMT,'management',ROOT],['222222222222','prod-web',PROD],['333333333333','prod-data',PROD],[DEV,'dev-sandbox',sandbox?SAND:PROD],['555555555555','log-archive',SEC],[AUDIT,'audit',SEC]].map(([id,name,parentId])=>({id,name,parentId,state:'ACTIVE',fixtureId:'original-'+id,email:name+'@example.invalid'}));
  const region=clone(REGION);if(broken)region.Statement[0].Condition={StringEquals:{'aws:RequestedRegion':'ap-south-1'}};
  return {region:'us-east-1',callerIdentity:{Account:MGMT,Arn:`arn:aws:iam::${MGMT}:role/org-operator`,UserId:'TRAINING'},organization:{id:'o-shop123456',managementAccountId:MGMT,rootId:ROOT,email:'org-operator@example.invalid',featureSet:'ALL'},orgPolicyTypes:['SERVICE_CONTROL_POLICY'],orgAccounts:accounts,orgUnits:units,orgOuSequence:sandbox?4:3,orgRevision:1,orgServiceAccess:sandbox?[SERVICE]:[],orgDelegates:sandbox?[{accountId:AUDIT,service:SERVICE,id:'original-config-delegation'}]:[],orgRoleIdentityPolicy:clone(IDENTITY),
   scps:[{id:'p-FullAWSAccess',name:'FullAWSAccess',description:'AWS managed Allow baseline',awsManaged:true,revision:1,document:clone(FULL),targets:[ROOT,...units.map(u=>u.id),...accounts.map(a=>a.id)].filter(id=>!broken||id!==W)},{id:'p-region01',name:'SandboxRegion',description:'Review ki scoped region/location limit',awsManaged:false,revision:1,document:region,targets:sandbox?[SAND]:[]},{id:'p-notrail1',name:'ProtectAuditTrail',description:'Reviewed trail protection',awsManaged:false,revision:1,document:clone(PROTECT),targets:sandbox?[SAND]:[]},...(broken?[{id:'p-pathdeny',name:'IncompleteAllowList',description:'Sirf Deny wala badlav koi Allow nahi chhodta',awsManaged:false,revision:1,document:{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]},targets:[W]}]:[])],
   queues:[{name:'prod-orders',queueId:'original-prod-orders',arn:'arn:aws:sqs:ap-south-1:222222222222:prod-orders',url:'https://sqs.ap-south-1.amazonaws.com/222222222222/prod-orders',ownerAccount:'222222222222',isFifo:false,visibilityTimeout:120,messages:[{messageId:'original-work101',body:'{"orderId":"accepted101","total":499}',visibleAt:0,sentAt:0,receiveCount:0}]}],rds:[{id:'prod-orders',resourceId:'db-original-org-orders',name:'prod-orders',engine:'postgres',class:'db.t3.medium',state:'available',multiAZ:true,backupRetention:7,encrypted:true,publicAccess:false,deletionProtection:true,storage:100,dataFixture:[{orderId:'accepted101',total:499}]}]
  };
 }
 const initial=seed(),sandbox=s=>s.account.orgUnits.find(u=>u.name==='Sandbox'&&u.parentId===W);
 function preserved(s){const a=s.account;return same(a.organization,initial.organization)&&same(a.orgPolicyTypes,['SERVICE_CONTROL_POLICY'])&&a.orgAccounts.length===6&&initial.orgAccounts.every(orig=>{const c=a.orgAccounts.find(c=>c.id===orig.id);return !!c&&c.fixtureId===orig.fixtureId&&c.name===orig.name&&c.state==='ACTIVE'&&(c.id===DEV||c.parentId===orig.parentId);})&&initial.orgUnits.every(u=>same(a.orgUnits.find(x=>x.id===u.id),u))&&same(a.orgRoleIdentityPolicy,IDENTITY)&&a.queues.length===1&&a.queues[0].queueId==='original-prod-orders'&&a.queues[0].messages.length===1&&a.queues[0].messages[0].messageId==='original-work101'&&a.queues[0].messages[0].body===initial.queues[0].messages[0].body&&a.rds.length===1&&same(a.rds[0],initial.rds[0]);}
 function baseline(s,interview=false){const a=s.account,u=sandbox(s),full=a.scps.find(p=>p.id==='p-FullAWSAccess'),ids=[ROOT,W,PROD,SEC,...initial.orgAccounts.map(c=>c.id),...(u?[u.id]:[])].sort();if(a.scps.length!==(interview?4:3)||!full||!full.awsManaged||!same(full.document,FULL)||!same((full.targets||[]).slice().sort(),ids))return false;if(interview){const p=a.scps.find(p=>p.id==='p-pathdeny');return !!p&&same(p.targets,[W])&&same(p.document,{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]});}return true;}
 function requests(a,identity='allow',boundary='none',resourcePolicy='none'){
  const request=(action,region,location,resource='*',rp='none')=>AG.orgRequestDecision(a,{accountId:DEV,principalType:'role',principalArn:`arn:aws:iam::${DEV}:role/sandbox-dev`,action,resource,region,location,identity,boundary,resourcePolicy:rp});
  return [request('s3:CreateBucket','ap-south-1','ap-south-1','arn:aws:s3:::training-new'),request('s3:CreateBucket','eu-west-1','ap-south-1','arn:aws:s3:::training-new'),request('s3:CreateBucket','ap-south-1','eu-west-1','arn:aws:s3:::training-new'),request('cloudtrail:StopLogging','ap-south-1'),request('s3:PutObject','ap-south-1',undefined,'arn:aws:s3:::sandbox-data/training.txt',resourcePolicy)];
 }
 function guardrails(s){const a=s.account,u=sandbox(s),p=a.scps.find(p=>p.id==='p-region01'),t=a.scps.find(p=>p.id==='p-notrail1');if(!u||a.orgUnits.length!==4||a.orgAccounts.find(c=>c.id===DEV)?.parentId!==u.id||!p||!t||!same(p.document,REGION)||!same(t.document,PROTECT)||!same(p.targets,[u.id])||!same(t.targets,[u.id]))return false;const r=requests(a);return r[0].allowed&&!r[1].allowed&&!r[2].allowed&&!r[3].allowed&&r[4].allowed;}
 function delegated(s){const a=s.account;return a.orgServiceAccess.length===1&&a.orgServiceAccess[0]===SERVICE&&a.orgDelegates.length===1&&a.orgDelegates[0].accountId===AUDIT&&a.orgDelegates[0].service===SERVICE&&(a.orgDelegationReads||[]).some(r=>r.revision===a.orgRevision&&r.service===SERVICE&&same(r.ids,[AUDIT]));}
 const solution=[`aws organizations create-organizational-unit --parent-id ${W} --name Sandbox`,`aws organizations move-account --account-id ${DEV} --source-parent-id ${PROD} --destination-parent-id ${SAND}`,`aws organizations attach-policy --policy-id p-region01 --target-id ${SAND}`,`aws organizations attach-policy --policy-id p-notrail1 --target-id ${SAND}`,`aws organizations enable-aws-service-access --service-principal ${SERVICE}`,`aws organizations register-delegated-administrator --account-id ${AUDIT} --service-principal ${SERVICE}`,`aws organizations list-delegated-administrators --service-principal ${SERVICE}`];
 const tasks=[{text:'Purane accounts/Production + Security OUs, IAM grant aur production order DB/queue bache rahe',check:s=>preserved(s)&&baseline(s)},{text:'Workloads ke neeche Sandbox, dev account shift hua, review ki scoped policies lagi aur requests ke asli contracts sahi',check:guardrails},{text:'Config rules/conformance-pack ka trusted access + audit delegation register hua aur aaj ki registry padhi',check:delegated}];
 const isolution=[`aws organizations attach-policy --policy-id p-FullAWSAccess --target-id ${W}`,'aws organizations update-policy --policy-id p-region01 --content file://region.json','aws organizations describe-policy --policy-id p-region01'];
 const itasks=[{text:'Purana account/tree/production ka kaam aur IAM grant bache rahe',check:s=>preserved(s)&&baseline(s,true)&&sandbox(s)?.id===SAND&&sandbox(s)?.fixtureId==='original-sandbox'},{text:'Sandbox ki review ki asli limits; kisi ancestor par Allow ki kami nahi, na ulti region condition',check:guardrails},{text:'Purana service ka delegation/access bacha; theek hui region policy ka aaj ka content padha',check:s=>{const a=s.account,p=a.scps.find(p=>p.id==='p-region01');return !!p&&same(a.orgServiceAccess,[SERVICE])&&same(a.orgDelegates,[{accountId:AUDIT,service:SERVICE,id:'original-config-delegation'}])&&(a.orgPolicyReads||[]).some(r=>r.id===p.id&&r.revision===p.revision&&same(r.document,p.document));}}];
 function board(k){const a=seed(true),full=a.scps[0];for(const [id,allow]of [[ROOT,k.root],[W,k.ou],[DEV,k.account]])if(!allow){full.targets=full.targets.filter(t=>t!==id);a.scps.push({id:'p-gap-'+id,targets:[id],document:{Version:'2012-10-17',Statement:[{Effect:'Deny',Action:'s3:DeleteBucket',Resource:'*'}]}});}if(k.guard===0)a.scps[1].targets=[];if(k.guard===2)a.scps[1].document.Statement[0].Condition={StringEquals:{'aws:RequestedRegion':'ap-south-1'}};const r=requests(a,['none','allow','deny'][k.iam],['none','allow','deny'][k.boundary],['none','allowRoleArn','deny'][k.resource]),ok=r[0].allowed&&!r[1].allowed&&!r[2].allowed&&!r[3].allowed&&r[4].allowed;return {r,ok};}
 AG.registerLevels('advanced',[{
  id:'orgs',icon:'🏢',title:'Organizations: boundaries, grants aur guardrails',badge:'Landing Zone Lord',
  objectives:['Account/OU design se nuksaan ka daayra (blast radius) aur ownership ka scope samajhna','Root → OU → account ki SCP limits aur IAM/resource grant ka raasta jaanchna','Identity Center, Control Tower, RAM aur service delegation chunna','Aaj ke policy types/billing/tagging ki boundaries ke saath safe canary governance set karna'],
  hook:{when:'ShopKaro course ki kahani (fictional)',title:'40 engineers, shared access aur galat workspace mein destroy',text:'Ravi ne dev samajh kar Terraform destroy chalaya; chaude credentials ne prod ki queue delete kar di. Tags ne alag ownership nahi di. Neha ko account ka alag hona, chhota human access aur exception ka raasta chahiye; ek badi AdministratorAccess policy recovery plan nahi.',mission:'Ek chhoti Sandbox boundary banao, sirf sahi dev account shift karo, review ki limits lagao aur ek service ka audit delegate register karo. Production ka kaam bachao. Moto ka metadata asli AWS ke laagu hone ka saboot nahi.'},
  steps:[
   {q:'Account boundary mazboot hai; phir bhi poora bachav kyun nahi?',analogy:'Alag bank lockers chaabiyan aur records alag rakhte hain. Par har team ko di gayi ek master key us alag hone ko paar kar sakti hai.',body:'<p>AWS accounts resource/identity/billing aur kai account/Region quotas ki mazboot boundary dete hain. Production aur non-production ko saaf ownership ke neeche rakho aur cross-account trust kam rakho. Account ka alag hona un credentials ya roles se nahi bachata jinhe accounts ke paar permission di gayi ho, na shared dependencies ya management ke hack hone se.</p>',points:['Course ki kahani: 40 engineers shared chaude access se aage badh kar management, Security (log-archive/audit), Infrastructure aur Workloads (Production/Dev/Sandbox) tak jaate hain. OUs ko shared policy ki zarooraton se group karo, sirf org-chart ki copy banane ke liye nahi.','Galti jo sab karte hain: tags ko permission ki boundary samajhna, ya maan lena ki har quota sirf har account ka hai, bina Region/service ke exceptions ke. Tags allocation/ABAC mein sirf wahan madad karte hain jahan asli policy/service us condition ko support kare.','Hands-on: main mission sirf dev-sandbox ko shift karta hai. Expected: prod-web/prod-data aur purana orders DB/queue waise hi rahein; production account ko Sandbox mein le jaana sahi fix nahi.'],asli:'Management account sirf un kaamon ke liye use karo jinhe uski zaroorat hai, workloads kahin aur rakho, root/break-glass access bachao aur cross-account trust review karo. SCPs management identities par limit nahi lagate.'},
   {q:'SCP ke raaste mein Allow aur Deny ka exact niyam kya hai?',analogy:'Building, floor aur lab, teeno ko andar jaane ki permission deni chahiye. Koi bhi lagu saaf rok andar jaane se rokti hai; floor ka pass building ki limit ko override nahi kar sakta.',body:'<p>SCPs member identities par limit lagate hain, member root aur delegated-administrator accounts par bhi; yeh access dete nahi. Root, raaste ke har OU aur target account par lagu Allow dekho, phir saare lagu Denies. Ek node par kai policies Allow jod sakti hain; nodes ke paar har level ko allow karna padta hai. Koi bhi lagu saaf Deny jeetta hai.</p>',points:['SCPs on karne par FullAWSAccess baseline apne aap lagta hai, taaki chaudi limits bani rahein. FullAWSAccess hatane se sab band ho jaaye, aisa zaroori nahi agar koi aur lagu Allow bacha ho; par raaste ke kisi zaroori level par Allow na bache toh request ruk jaati hai.','Management identities aur service-linked roles SCP ki rok se bahar hain; yeh chhoot manmaani IAM/service permission nahi deti. Member resource ko access karne wale bahar ke principals sirf isliye resource owner account ke SCP se nahi rukte ki resource wahan hai. Supported resource limits ke liye RCPs alag hain.','Hands-on: dry run/board mein ek ancestor ka Allow hatao jabki IAM admin rahe. Expected: missing path layer par deny. Koi bada Region rule lagane se pehle supported global-service exceptions review karo.'],asli:'2025 ke poore IAM-language expansion ke baad SCP Allow conditions/resources/NotAction use kar sakta hai; NotResource aur chaude Action wildcards bhi hain. Local evaluator chhota supported hissa batata hai; purane "yeh syntax nahi chalta" wale niyam ab purane hain.'},
   {q:'SCP grant nahi deta; IAM/resource/boundary ka mel kaise padhein?',analogy:'Building ki limit andar aane deti hai, par sahi invitation phir bhi chahiye. Kisi kamre ki khaas invitation bhi ek grant ho sakti hai; saaf rok phir bhi maayne rakhti hai.',body:'<p>Identity policies actions ki permission deti hain; permissions boundaries aur session policies lagu grant ke raaste ko limit kar sakti hain. Resource-based grants principal ke type ke hisaab se alag hote hain. Same-account role-ARN case mein resource policy identity Allow ke bina object access de sakti hai, jabki boundary/session-policy ka implicit deny phir bhi us role grant ko limit karta hai. Seedhe user/session ARN aur wildcard Principal+PrincipalArn raaston ke exceptions alag hain.</p>',points:['Board same-account role ka model hai: s3:PutObject ke liye pehle se bane bucket par optional role-ARN grant, identity grant/saaf Deny, ek boundary aur SCPs. Isme seedhe user/session ARN grants, cross-account trust, session policies, RCPs aur poora IAM engine nahi.','CreateBucket ko aage banne wale, abhi na bane bucket ki policy se permission nahi mil sakti. Optional resource policy sirf pehle se bane PutObject wale scenario par lagti hai. Saaf identity/resource Deny aur lagu SCP limit phir bhi rokti hai.','Hands-on: IAM Allow hatao par role-ARN resource Allow chuno. Expected: boundary/SCP allow karein toh pehle se bane bucket mein PutObject pass ho sakta hai; CreateBucket phir bhi fail. Dono contracts poore karne ke liye IAM Allow wapas lagao.'],asli:'Simple SCP∩IAM formula har resource-policy/principal case par mat lagao. Principal, resource owner, grant ka raasta aur lagu Denies ka naam lo.'},
   {q:'Employees ka access ek jagah se karein, aur service roles ko kaise alag pehchanein?',analogy:'Ek employee badge portal har building ka sahi pass deta hai; isse har employee building ka maalik nahi ban jaata.',body:'<p>IAM Identity Center employees ke users/groups ko supported applications/accounts se jodta hai. Ek supported organization-instance workflow permission sets se account roles banata hai aur groups ko assign karta hai. Account instances alag supported applications ke liye hain; organization instances kai accounts ka AWS access dete hain. Aaj ke account-access-manager workflows pehle se bane roles ko bhi ek jagah la sakte hain. Customer app login ek alag, Cognito jaisi zaroorat hai.</p>',points:['Thodi der ke scoped account sessions, MFA/IdP controls, review kiye group assignments aur offboarding use karo. Identity Center portal SCPs, boundaries ya resource permission ko override nahi karta. Machine workloads sahi IAM/service roles use karein, shared human access key nahi.','Delegated administrator ek member account mein ek service ki authority hai, management ownership ya SCP se chhoot nahi. Config rules/conformance packs config-multiaccountsetup.amazonaws.com use karte hain; aggregation ka integration alag config.amazonaws.com hai. GuardDuty/SecurityHub ke apne setup workflows hain.','Hands-on: main trusted access on karne ke baad likhe Config rules/conformance-pack integration ke liye audit register karta hai. Sirf registry ka metadata; koi Config rules/recorders ya Identity Center service deploy nahi hoti.'],asli:'Har service ka supported admin API, trusted access ki zarooratein aur zaroori runtime config check karo. Sirf Organizations mein register karna poori service set nahi karta.'},
   {q:'Control Tower ka baseline kaun se raaste ko govern karta hai?',analogy:'Ek housing builder standard wiring, inspection ke niyam aur ek jaisa handover deta hai. Standard template se yeh pakka nahi ki baad ki har marammat usi tareeke se hui.',body:'<p>Control Tower landing zone banata/govern karta hai, aur Account Factory baseline ke saath baar-baar ek jaisa account banane mein madad karta hai. Region/control ka coverage, enrollment aur drift review karo. Aaj ke preventive controls SCPs/RCPs/declarative policies use karte hain; detective controls AWS Config rules; proactive controls supported create/update raaston se pehle CloudFormation Hooks.</p>',points:['Proactive CloudFormation controls ka matlab yeh nahi ki har seedhi SDK/API ya Terraform AWS-provider request check hui. Control Tower ke controls ko Terraform se chalana alag hai, aur isse har Terraform resource CloudFormation hook se paas nahi hota.','Galti jo sab karte hain: ek click wale landing zone ko saara compliance/risk ka kaam poora samajhna. Ownership, identity, networks, service coverage, exceptions aur controls ke asli results ka saboot phir bhi chahiye.','Hands-on: bins mein grant, permission ki limit aur baseline/detection/provisioning control ko alag karo. Expected: Account Factory chuna account baseline banata hai; yeh permission grant nahi.'],asli:'Pehle control ko ek alag OU/account par canary ki tarah lagao, rollback/exception ke owner ke saath. Organization root par bina test ka chauda Deny mat lagao.'},
   {q:'Central logging ko chhed-chhaad se kaise bachayein?',analogy:'CCTV recording ko alag, taale wale archive mein rakho. Archive ki chaabi har visitor ko dena ya retention policy bhoolna alag rakhne ka fayda mita deta hai.',body:'<p>Organization trail chune member activity ko alag log-archive account mein ek jagah la sakta hai. Destination/KMS ki ownership aur policies, delegated service authority, log delivery/validation aur zaroori retention review karo. Member identities ke liye SCP ka bachav alag rakhne mein madad karta hai; yeh management identities ya service-linked roles par limit nahi lagata.</p>',points:['Object Lock mode, retention/legal hold aur allowed principals maayne rakhte hain. Governance mode allowed bypass permissions se bypass ho sakta hai; compliance mode ka retention behaviour alag hai. Sirf trail destination har jagah chhed-chhaad se bachne ki guarantee nahi.','RequestedRegion request ka endpoint control karta hai, aage ka saara data kahan jaayega, yeh nahi. Course policy EC2/RDS/S3CreateBucket endpoints ko Mumbai tak rakhti hai aur S3LocationConstraint alag se check karti hai. Global services ko soch kar review karna padta hai; yeh example poori data-residency policy nahi.','Hands-on: triage mein OU policies, asli parent path aur maanga endpoint/location dekho. Expected: aaj ki limit ya missing Allow pehchano, baar-baar IAM admin access chauda karne ki jagah.'],asli:'Asli pahunche logs/digests, integrity validation, access/retention aur response ka owner check karo. Local org/SCP metadata in production results ko prove nahi kar sakta.'},
   {q:'RAM, billing aur delegation se shared ownership ban jaati hai?',analogy:'Shared kitchen ki booking doosri team ko saamaan use karne deti hai; maalik, chalane ke niyam aur bill ka samjhauta phir bhi rehte hain.',body:'<p>AWS RAM subnets/TGW jaise supported resources allowed accounts/OUs/principals ke saath share karta hai. Maalik wahi rehta hai; use karne wale account ke grants aur limits phir bhi lagte hain. Supported resource types, region ka scope aur invitation/organization sharing ka setup alag hote hain. Resource share karna account ki ownership dena nahi.</p>',points:['Consolidated billing eligible usage/discounts aur accounts ka kharcha data jodti hai; ek bill seller-of-record boundaries par depend kar sakta hai. Eligible RI/Savings Plans ke fayde aaj ki billing preferences ke hisaab se baante jaate hain, jisme open/prioritized/restricted group sharing bhi hai. Khareedne wale account ki eligibility aur sharing settings maayne rakhti hain; koi pakka percentage bachat nahi.','Galti jo sab karte hain: discount sharing ko chalti capacity reservation, dohraaya Free Tier, bina limit shared quotas ya permission sharing samajhna. Billing aur permission ke contracts alag hain.','Hands-on: shared subnet, cross-account role, delegated Config admin aur billing preference compare karo. Expected: supported resource sharing ke liye RAM, access ke liye IAM/Identity Center, administration ke liye service delegation, eligible faydon ke liye billing preferences.'],asli:'Ek jagah laane se badalta hai ki kaun chalata hai aur kaun paise deta hai; owner, permission, failure aur kharche ke bantwaare ki boundaries saaf rakho.'},
   {q:'Tag, backup, RCP aur declarative policies ko SCP kyun na samjhein?',analogy:'Kharche ke labels, backup ka schedule, locker ke access ki limit aur poori building ki safety ka config: alag niyam hain, alag jagah laagu hote hain.',body:'<p>Tag policies mein basic key/value/case ki consistency hai, aur aaj Required-tag-key/reporting/IaC workflows bhi. Basic consistency wali enforcement missing tags ko nahi rokti. Required-key reporting/IaC validation ki apni tooling/resource dikhne ki limits hain; supported request-tag SCP/IAM conditions kuch create APIs ko rok sakti hain. Backup policies supported backup config ek jagah se tay karti hain; jobs, selections, copies aur restores ka asli saboot chahiye.</p>',points:['RCPs member accounts ke supported resources par permission ki limit hain, bahar ke principals ke access par bhi; yeh access nahi dete, management account ke resources ya service-linked roles ki calls ko govern nahi karte. Supported services ki list badalti rehti hai; S3 aaj ka ek example hai, yeh daava nahi ki har service RCPs support karti hai.','Declarative policies supported service ki control-plane settings laagu karti hain aur principal/API ki permission ki limits se alag hain. Inki supported settings service-linked role ke behaviour ko bhi govern kar sakti hain. SCP ka inheritance/evaluation tag/backup/declarative policy types par aankh band karke mat lagao.','Hands-on: lab22 asli organization attachment/delegation aur ek mana ki gayi member request check karta hai. Expected: Deny ke bawajood Moto mana kiya bucket bana deta hai; limit wala evaluator likha hua logic sikhata hai. Tag/RCP/backup/declarative ke runtime enforcement ka daava nahi.'],asli:'Control ke goal, supported resource/API aur aaj ke enforcement/reporting mode se policy chuno. Rollout se pehle coverage aur exceptions check karo.'}
  ],
  myth:[{myth:'Accounts guarantee dete hain ki chaude cross-account credentials production ko chhoo nahi sakte.',sach:'Accounts resources ko alag rakhte hain; trust/permissions aur shared credentials us boundary ko paar kar sakte hain. Access kam karo aur recovery ka saboot bachao.'},{myth:'FullAWSAccess hatane se hamesha poori organization band ho jaati hai.',sach:'Request ko raaste ke har level par lagu Allow chahiye. Review kiya badlav permission bacha sakta hai; missing Allow ya saaf Deny rok deta hai.'},{myth:'SCP, resource policy aur IAM grants hamesha ek simple intersection banate hain.',sach:'SCP ki limits aur saaf Denies rehte hain, par asli grant/implicit-deny ke niyam principal/resource ki ownership aur grant ke raaste par depend karte hain.'},{myth:'Laga hua metadata ya ek central trail production governance prove karta hai.',sach:'Asli supported enforcement, delivery, retention, identity aur exceptions test karo. Moto aur service ki zarooraton ki saaf kamiyan hain.'}],
  playbook:{title:'Boundary → grant → limit → check kiya rollout',use:['Production/non-production ki ownership alag rakho aur cross-account trust ko limit mein rakho.','Canary tests ke baad member OU guardrails lagao, zaroori Allow raaste bachate hue.','Service operations ka delegation chhota rakho; employees ka access aur supported resource sharing alag tools se ek jagah lao.'],avoid:['Bina test ka poore root par Deny, har global service rok dena, ya maan lena ki Region = saara data kahan hai.','IAM grants ki jagah SCP Allow lagana, ya maan lena ki SCP management/SLRs ko bhi rokta hai.','Metadata, discounts ya policy ke naam se compliance bol dena.'],how:['Caller/principal ka type, resource owner, action aur request ka context pehchano.','Root → har OU → account ke Allows aur lagu saaf Denies dekho.','Identity/resource grant ka raasta aur boundary/session/RCP ka scope pehchano.','Alag canary par rollout karo, asli results check karo, owner/exception/rollback likho.'],redflags:['Admin ko deny: missing ancestor Allow, upar se aaya Deny, boundary ya resource policy; sirf typo nahi.','Tag value ki consistency ko har jagah missing-tag ki rok bolna.','Service delegation register hua par trusted access/runtime setup missing.'],rule:'Kaunsi boundary access deti hai, kaunsi limit request rokti hai, aur kaunsa asli service test vaada kiya control saabit karta hai?'},
  exam:[{cue:'Grant versus ceiling',pick:'IAM/resource grant ka raasta; SCP kabhi grant nahi deta'},{cue:'Inherited member permission',pick:'Root/har OU/account par Allow; koi bhi lagu Deny jeetta hai'},{cue:'Management / service-linked role',pick:'SCP se chhoot; bina limit permissions nahi'},{cue:'Workforce multi-account portal',pick:'Identity Center organization instance + review kiye assignments'},{cue:'New account baseline',pick:'Control Tower Account Factory; coverage/drift phir bhi review karo'},{cue:'Supported subnet/TGW share karo',pick:'RAM; resource owner ke paas rehta hai aur use karne wale ki permissions lagti hain'},{cue:'Member service administrator',pick:'Service ka delegation/zarooratein; SCP ki limit phir bhi'},{cue:'S3Region restriction',pick:'RequestedRegion endpoint + sahi LocationConstraint ka review'},{cue:'Tag/RCP/declarative ka goal',pick:'Alag supported coverage aur enforcement ke niyam'}],
  lesson:['<h3>Kab kya: control chunna</h3><div class="tbl-wrap"><table class="review-table"><tr><th>Goal</th><th>Option</th><th>Limit</th></tr><tr><td>Member identity ki limit</td><td>SCP</td><td>Grant nahi; management/SLR ke exceptions</td></tr><tr><td>Employees ko account access dena</td><td>Identity Center/IAM role</td><td>Assignments/trust/limits phir bhi lagte hain</td></tr><tr><td>Account ka standard baseline</td><td>Account Factory</td><td>Enrollment/control coverage/drift</td></tr><tr><td>Supported resource sharing</td><td>RAM</td><td>Owner aur use karne wale ki permissions rehti hain</td></tr><tr><td>Member resource ki limit</td><td>RCP</td><td>Supported resources/principals; grant nahi</td></tr><tr><td>Service ka chaaha hua config</td><td>Declarative policy</td><td>Supported settings/control-plane ka scope</td></tr><tr><td>Labels / backup plans</td><td>Tag / backup policy</td><td>Mode/dikhna/jobs/restore ka saboot</td></tr></table></div><p>Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p><p><b>Faisla kaise karein:</b> grant chahiye? Employees → Identity Center/IAM; supported shared resource → RAM + permissions. Limit chahiye? Member identity → SCP; supported member resource → RCP. Service ka baseline chahiye? Control Tower/declarative settings. Tagging/backup config chahiye? Uski policy + aaj ka coverage aur asli check.</p>'],
  stages:[
   {type:'dryrun',title:'🧪 Ek request, kai alag faisle',intro:'Fictional Sandbox role ki request. "Agla" click karo; panels lagu limit aur grant ka raasta dikhate hain, live AWS permission nahi.',lesson:'Root/har OU/account ki limits, saaf Denies, principal ka type aur asli grant ka raasta maayne rakhte hain. Is walkthrough mein poora IAM/session/RCP evaluation nahi.',nodes:[N('iam',150,150,{label:'Root ceiling'}),N('org',470,150,{label:'OU ceilings'}),N('account',790,150,{label:'Member role'}),N('s3',790,420,{label:'Existing object'}),N('iam#grant',470,420,{label:'Grant / boundary'})],edges:[{from:'iam',to:'org'},{from:'org',to:'account'},{from:'account',to:'s3'},{from:'s3',to:'iam#grant'}],panels:[{id:'ceiling',title:'SCP raasta / principal ka scope'},{id:'grant',title:'Grant / boundary / request ka context'}],steps:[
    {say:'Member role Mumbai endpoint par Mumbai LocationConstraint ke saath CreateBucket maangta hai. Root ka FullAWSAccess limit allow karta hai; IAM grant phir bhi alag hai.',panels:{ceiling:['Root Allow found','SCP koi permission nahi deta'],grant:['Identity policy ko yeh create request allow karni chahiye','Aage banne wale bucket ki koi bucket-policy grant nahi']}},
    {say:'Workloads mein sirf DeleteBucket ka Deny hai, koi lagu Allow nahi. Sandbox/account par FullAWSAccess hai; role ke paas AdministratorAccess hai.',panels:{ceiling:['Workloads: raaste ka Allow missing','Child ka Allow ancestor ki limit chaudi nahi kar sakta'],grant:['AdministratorAccess SCP raaste ki kami theek nahi kar sakta']},ask:Q('Missing ancestor Allow wale case mein permission ka faisla kya hona chahiye?', 'Child FullAWSAccess aur IAM admin ke bawajood Workloads par deny; review ke baad sahi Allow raasta wapas lao',['Allow, kyunki target account par FullAWSAccess hai aur child policy hamesha har ancestor policy ko override karti hai','Allow, kyunki AdministratorAccess ek identity grant hai jo upar se aayi organization limits apne aap band kar deta hai','Sirf tab deny jab role management account mein ho, kyunki SCPs sirf management identities par lagte hain'],0,'Raaste ke har zaroori level ko allow karna padta hai. Child ya IAM admin ancestor ki limit chaudi nahi kar sakte; management identities SCP se chhooti hain, woh akeli roki jaane wali identities nahi.')},
    {say:'Review kiya Allow raasta wapas lao. Ek alag request: same account ke pehle se bane bucket par PutObject. Bucket policy role ARN ko grant deti hai; IAM mein Allow nahi, aur role ki boundary action allow karti hai.',panels:{ceiling:['Raaste ke saare levels allow karte hain; koi saaf Deny nahi'],grant:['Pehle se bana role-ARN resource grant PutObject ki permission de sakta hai','Boundary phir bhi is role-ARN grant ko limit karti hai']},ask:Q('Is same-account role-ARN object grant ke raaste se kya nikalta hai?', 'PutObject identity Allow ke bina bhi allow ho sakta hai, agar resource grant, boundary aur lagu limits allow karein',['PutObject deny hona chahiye, kyunki resource-based policies kabhi grant nahi hoti, sirf IAM permissions hataati hain','Resource Allow har SCP Deny ko override karta hai, kyunki object ka maalik member roles ki organization limits hata sakta hai','Resource grant kisi bucket ke banne se pehle CreateBucket bhi allow karta hai, kyunki saari S3 permissions ek hi future policy share karti hain'],1,'Same-account role-ARN resource grant ek asli grant hai, lagu boundary/limits ke andar. Yeh SCP Deny override nahi kar sakta, na na-bane bucket ki policy se creation de sakta hai; doosre principal types ke niyam alag hain.')},
    {say:'Ab ek scoped policy CreateBucket ko Mumbai endpoint ke bahar ya non-Mumbai LocationConstraint ke saath deny karti hai. Sirf allowed endpoint se har jagah data residency saabit nahi hoti.',panels:{ceiling:['Review kiya service/action ka scope','Global services par poori rok nahi'],grant:['Endpoint Region aur sahi destination ka context alag hain','Service API ke asli niyam check karo']}},
    {say:'Audit account Config ka delegated administrator banta hai. Account phir bhi member hi hai; uske human/service roles SCP ke andar rehte hain, service-linked role ke behaviour ko chhod kar.',panels:{ceiling:['Delegation member account ko chhoot nahi deta','Management/SLR ki SCP chhoot alag hai'],grant:['Trusted access + service ka registration metadata','Config ka runtime setup phir bhi alag']},ask:Q('Service delegation ke baad account/principal ke baare mein kaunsa daava sahi hai?', 'Delegated member identities SCP ke andar rehti hain; management identities aur service-linked roles ko SCP se chhoot hai',['Audit account management ka maalik ban jaata hai aur har purane SCP aur IAM boundary se apne aap chhoot jaata hai','Delegated admin saare member accounts ke har user ko nayi IAM permissions deta hai, kyunki registration identity policy ki jagah le leta hai','Saare service roles ko chhoot hai, kyunki service-linked roles aur aam application/service execution roles ek hi hain'],2,'Delegation ek service ke liye hai aur account ki ownership nahi badalta, na har identity ko access deta hai. Management/SLR ki chhoot khaas hai; aam execution roles apne aap service-linked roles nahi hote.')},
    {say:'Aaj ka parent path, review ki policy ka content aur service registry padho. Local config/evaluator contracts ready ho sakte hain; asli AWS enforcement aur service runtime ke liye canary chahiye.',panels:{ceiling:['Purane production accounts/kaam bache','Aaj ka tree/policies, command history ke shabd nahi'],grant:['Moto SCP ke bawajood mana kiye region ki request maan leta hai','Production enforcement ka koi certificate ka daava nahi']}}
   ]},
   {type:'flowlab',title:'🎛️ Permission calculator: bataya role ka raasta',goal:'Mumbai/Mumbai CreateBucket aur pehle se bane Mumbai PutObject ko allow karo; EU endpoint ka create, Mumbai endpoint/EU location ka create aur StopLogging deny karo. Shuru: Root/OU/account Full, review kiya Region guard, IAM Allow, boundary None, resource None.',scenario:'Limit wala same-account member role. Teen limit ke knobs Full Allow aur ek sahi Deny-only baseline (jo maanga Allow missing chhodta hai) mein chunte hain. Region guard EC2/RDS/S3CreateBucket endpoints + S3LocationConstraint ko scope karta hai; audit StopLogging Deny pehle se laga hai. Optional resource policy sirf pehle se bane PutObject par lagti hai aur role ARN ko grant deti hai, user/session ARN ko nahi. Identity/resource ka saaf Deny jeetta hai; role ki boundary phir bhi us role-ARN grant ko limit karti hai. Cross-account/session-policy/RCP/poora IAM evaluation ya live AWS call nahi.',knobs:[{id:'root',label:'Root path Allow',min:0,max:1,step:1,value:1,labels:{0:'Allow missing',1:'Full Allow'}},{id:'ou',label:'Workloads OU Allow',min:0,max:1,step:1,value:0,labels:{0:'Allow missing',1:'Full Allow'}},{id:'account',label:'Target account Allow',min:0,max:1,step:1,value:1,labels:{0:'Allow missing',1:'Full Allow'}},{id:'guard',label:'Region/location policy',min:0,max:2,step:1,value:2,labels:{0:'Not attached',1:'Reviewed NotEquals',2:'Wrong Equals'}},{id:'iam',label:'Role identity policy',min:0,max:2,step:1,value:1,labels:{0:'No grant',1:'Allow',2:'Explicit Deny'}},{id:'boundary',label:'Role permissions boundary',min:0,max:2,step:1,value:0,labels:{0:'None',1:'Allows request',2:'Does not allow'}},{id:'resource',label:'Pehle se bane object ki resource policy',min:0,max:2,step:1,value:0,labels:{0:'None',1:'Role-ARN Allow',2:'Explicit Deny'}}],model:k=>{const b=board(k),labels=['Create: Mumbai endpoint + location','Create: EU endpoint, Mumbai location','Create: Mumbai endpoint, EU location','StopLogging:Mumbai','PutObject: pehle se bana Mumbai object'];return {readouts:b.r.map((r,i)=>({label:labels[i],value:(r.allowed?'Allowed':'Denied')+' • '+r.layer})),verdict:{ok:b.ok,text:b.ok?'Bataye paanchon role/request contracts fit hain. Asli AWS enforcement aur doosre principal/grant raaston ke alag tests chahiye.':'Faisla karne wali har layer dekho; sahi access rakho aur galat endpoint/location aur audit ke saath chhed-chhaad roko.'}};},check:k=>board(k).ok,lesson:'SCP Allow ek limit hai, grant nahi. Root/OU/account raaste ki kamiyan member ko rokti hain. Role-ARN resource Allow boundary/limits allow karein toh IAM Allow ke bina pehle se bane bucket mein PutObject de sakta hai; aage banne wale bucket ki policy se CreateBucket nahi de sakta. Saaf Denies rehte hain. Yeh limit wala likha hua raasta hai, har jagah ka IAM formula nahi.'},
   {type:'bins',title:'Grant, limit, dono, ya service baseline?',instructions:'Bataye goal ke liye zaroori mukhya mechanism chuno. Chhoot, supported APIs aur service ka setup phir bhi lagte hain.',bins:[{id:'ceiling',label:'Authorization ceiling'},{id:'grant',label:'Grant / access'},{id:'both',label:'Grant + ceiling'},{id:'baseline',label:'Service / account baseline'}],items:[{text:'Canary testing ke baad bataye member regional APIs ko limit karo',bin:'ceiling',explain:'SCP review kiye actions/context ke liye member identities par cap laga sakta hai; management/SLR ki chhoot rehti hai.'},{text:'Employees ke group ko scoped production account access do',bin:'grant',explain:'Identity Center/IAM role assignments grant dete hain, phir bhi lagu limits ke andar.'},{text:'Dev bucket banana sirf review kiye Mumbai endpoint/location ki rok ke andar allow karo',bin:'both',explain:'Banane ke liye grant aur sahi organization/service-context guard dono chahiye; SCP akela grant nahi deta.'},{text:'Member role ko protected trail rokne/delete karne se roko',bin:'ceiling',explain:'Lagu SCP Deny us member role ko rok sakta hai; yeh har jagah chhed-chhaad-proof storage nahi.'},{text:'Chune landing-zone baseline ke saath naya account banao',bin:'baseline',explain:'Control Tower Account Factory account banane/baseline ka workflow hai, IAM grant nahi.'},{text:'Owner aur use karne wale ki permissions bachate hue ek supported subnet share karo',bin:'grant',explain:'RAM supported resource ko use layak banata hai; maalik wahi rehta hai aur use karne wala account scoped access deta hai.'},{text:'Supported organization backup settings set karo aur jobs/restores alag se check karo',bin:'baseline',explain:'Backup policies supported config tay karti hain, apne alag inheritance ke saath; yeh SCP ka grant/deny raasta nahi.'}]},
   {type:'fill',title:'✍️ Scoped SCP ka hissa: endpoint aur audit ki limit',instructions:'Teen khaali jagah bharo. Yeh hissa trail APIs aur bataye regional endpoints ko bachata hai; region.json S3LocationConstraint alag se check karta hai. Poori data-residency ki guarantee nahi.',template:'{\n "Version":"2012-10-17",\n "Statement":[\n  {"Effect":"{0}","Action":["cloudtrail:StopLogging","cloudtrail:DeleteTrail"],"Resource":"*"},\n  {"Effect":"Deny","Action":["ec2:*","rds:*","s3:CreateBucket"],"Resource":"*",\n   "Condition":{"{1}":{"aws:RequestedRegion":"ap-south-1"}}}\n ]\n}\n\naws organizations attach-policy --policy-id p-region01 --target-id {2}',tokens:['Deny','StringNotEquals',SAND,'Allow','StringEquals','arn:aws:iam::aws:policy/AdministratorAccess'],blanks:[{answer:'Deny',explain:'Lagu Deny member request ko rokta hai. Allow na permission deta, na trail ke saath chhed-chhaad rokta.'},{answer:'StringNotEquals',explain:'Mumbai ke bahar ke endpoints deny karo. StringEquals condition ko ulat deta hai aur apne ghar ka endpoint hi rok sakta hai.'},{answer:SAND,explain:'Sahi Sandbox OU ID par lagao, IAM policy ARN par nahi. Parent path aur alag location ki rok ka review phir bhi chahiye.'}]},
   {type:'triage',title:'🩺 Mumbai mein admin, phir bhi AccessDenied',symptom:'Fictional Sandbox role ke paas IAM AdministratorAccess hai. Mumbai LocationConstraint ke saath Mumbai CreateBucket fail hota hai. Root allow karta hai; organization config ki do alag galtiyan bachi hain.',goal:'IAM grant chauda karne se pehle ancestors aur policy ka asli content dekho.',commands:[{cmd:`aws organizations list-parents --child-id ${DEV}`,out:`Parents:[{Id:${SAND},Type:ORGANIZATIONAL_UNIT}]`,clue:false,note:'Account ka asli parent confirm karo, phir ancestors dekho; chaaha hua OU label aaj ki membership nahi.'},{cmd:`aws organizations list-policies-for-target --target-id ${W} --filter SERVICE_CONTROL_POLICY`,out:'IncompleteAllowList:Deny s3:DeleteBucket only; no applicable Allow at Workloads',clue:true,note:'Sirf Deny wala baseline is zaroori ancestor par maanga Allow missing chhod deta hai.'},{cmd:'aws organizations describe-policy --policy-id p-region01',out:'TRAINING Content:ScopedRegionalAPIs uses StringEquals aws:RequestedRegion=ap-south-1',clue:true,note:'Deny + Equals apne ghar ka endpoint rokta hai. Ancestor Allow ke saath review ki condition bhi theek karo.'},{cmd:'cat identity.json',out:'TRAINING role policy already grants s3:CreateBucket/s3:PutObject/cloudtrail:StopLogging',clue:false,note:'Grant lagu SCP limit chaudi nahi karta. StopLogging alag audit SCP se deny hi rehna chahiye.'}],questions:[Q('AdministratorAccess ke bawajood ghar ke region mein deny ki wajah kya hai?', 'Workloads par lagu Allow nahi aur regional Deny ulta Equals use karta hai; dono ka review ke saath repair chahiye',['Sirf IAM grant missing hoga, kyunki AdministratorAccess upar se aaye saare SCP restrictions apne aap hata deta hai','Target account ka FullAWSAccess har ancestor ko override karta hai, isliye ek hi wajah management account ki chhoot hai','Config delegate SCPs se chhoota hoga, isliye kisi bhi member ko delegate register karna sahi access repair hai'],0,'Raaste ka Allow gap aur ulta Deny, dono maayne rakhte hain. Admin SCP bypass nahi karta; child Allow ancestor ko chauda nahi kar sakta, aur service delegation member identity ko chhoot nahi deta.'),Q('Kaunsa badlav sahi guardrails rakhte hue sahi access wapas laata hai?', 'Workloads par sahi Allow wapas lao, review ki NotEquals/location policy update karo aur aaj ka theek hua content dekho',['Root se har SCP hatao aur saari organization policies band karo, kyunki limits na hona sahi governance ke barabar hai','Production accounts ko bina guard wale root mein le jao, taaki sandbox role policy context review kiye bina access wapas paa le','Dev ko naye naam ke bina guard wale OU mein le jao aur maan lo ki naya label sahi Region/audit protections bachata hai'],1,'Khaas raasta/condition theek karo aur sahi protections/kaam bachao. Limits band karna ya production hilana control ka goal mita deta hai; naya bina guard label sahi permission aur protection ka contract nahi bachata.') ]},
   {type:'terminal',title:'🖥️ Sandbox boundary aur ek service delegate banao',instructions:'Sirf app ka Organizations fixture. Management caller organization set karta hai; koi asli account banana, band karna ya AWS request nahi.',goal:'<p><b>1.</b> Workloads ke neeche Sandbox banao: '+W+'. Naye pehle OU ki ID hai: '+SAND+'; zaroorat ho toh list-organizational-units-for-parent dekho. Sirf dev-sandbox '+DEV+' ko Production '+PROD+' se naye Sandbox mein le jao. Purane 6 accounts aur Production/Security ki ownership rakho.</p><p><b>2.</b> Review kiye p-region01 aur p-notrail1 ko Sandbox par lagao. Pehle se laga FullAWSAccess baseline root/har OU/account ke raaste allow karta hai. Zaroori limit wale role contracts: Mumbai/Mumbai CreateBucket aur pehle se bana PutObject allow; EU endpoint, galat bucket location aur StopLogging deny. IAM grant identity.json mein hi rehta hai; SCP kuch grant nahi karta.</p><p><b>3.</b> Is service ke liye trusted access on karo: '+SERVICE+'; phir audit '+AUDIT+' ko sirf usi service ka delegate register karo, phir principal se filter karke poora list-delegated-administrators chalao. Aaj ki registry mein audit aana chahiye. Yeh Config rules/conformance-pack ka registration metadata hai, aggregator/rules/runtime ka setup nahi.</p><p>7 actions. Purana production DB/order queue/message, policy ki pehchaan aur pehle se bane accounts/OUs bachao. Guardrails hatana, production hilana, chaude policy badlav, delete hua kaam, purana/query-filter wala registry output, ya bina trusted access delegation nahi chalega. Asli AWS permission ke liye approved canary chahiye; Moto SCPs laagu nahi karta.</p>',account:seed(),files,tasks,solution,hints:['Aaj ka tree, region.json, audit.json aur identity.json dekho. Sirf sahi member shift karo, aur grant ko limit se alag pehchano.',solution.slice(0,2).join(' phir '),solution.slice(2,4).join(' phir '),solution.slice(4).join(' phir ')],success:AG.allOf(tasks),successText:'Purane production/accounts/kaam bache. Sandbox ki membership aur review ki asli limits paanchon role/request contracts se match karti hain; trusted Config integration/audit delegation aur aaj ki registry ready hain. Asli AWS enforcement, Config rules ya landing-zone runtime ka daava nahi.'},
   {type:'docker',title:'🐳 Lab22: asli org metadata, aur mana ki gayi request bhi maan li gayi',project:'22-org-scp-guardrails',goal:'Apna virtual organization sequence chalao aur asli metadata ko missing enforcement se compare karo.',why:'Moto bina trusted access ke registration aur Deny ke bawajood mana kiya member bucket maan leta hai; attachment runtime permission ka saboot nahi.',steps:[{text:'aws-gurukul se README/lab.py padho aur exact local script chalao.',cmd:'./docker-labs/.venv/bin/python -I docker-labs/22-org-scp-guardrails/lab.py',expect:'6 behaviour checks: virtual org/accounts/nested OU move/default FullAWSAccess/attachment/delegation/member identity/mana kiye region ki location.'},{text:'REGISTER WITHOUT TRUSTED ACCESS aur MEMBER OUTSIDE_REGION wali lines dekho.',expect:'Moto dono maan leta hai; sahi trusted-access raasta bhi dobara chalta hai. Laga hua Deny hote hue bhi member ka eu-west-1 bucket ban jaata hai. Local STS identity asli trust-policy ka check nahi.'},{text:'Cleanup aur State-vs-Status wala note padho.',expect:'Membership cleanup 7, scoped cleanup 8, OWNED MOTO STOPPED / LISTENER CLOSED. Koi asli account band nahi hua; RemoveAccountFromOrganization sirf membership hataata hai.'}],observe:Q('Lab22 ka result asal mein kya support karta hai?', 'Local org/tree/attachment/delegation metadata aur member identity check hue; SCP enforcement saaf alag nikla',['Attachment asli AWS permission prove karta hai, kyunki safal Organizations jawaab baad ki har member API ko jaanchta hai','Mana kiya bucket prove karta hai ki review kiya SCP access deta hai, kyunki Deny statement ko IAM Allow samjha jaata hai','Member hataana prove karta hai ki asli AWS accounts band hue aur saare charges ruke, kyunki organization membership hi ownership hai'],2,'Asli local metadata pass hua, par mana ki gayi request bina SCP enforcement ke maan li gayi. Deny grant nahi hai; membership hatana asli account band karna ya billing cleanup saabit karna nahi.')},
   {type:'quiz',title:'🎓 Governance ke faisle aur aaj ka scope',questions:[
    Q('Target account par FullAWSAccess hai; ek ancestor par lagu Allow nahi. IAM admin action maangta hai. Result?', 'Missing ancestor Allow se deny; member request ko root/OU/account raaste ka har level allow karna chahiye',['Allow, kyunki administrator ke liye account ka local Allow root aur OU ki limits se zyada priority rakhta hai','Allow, kyunki FullAWSAccess ek identity grant hai jo account ke raaste ki kisi bhi missing organization policy ki jagah le leta hai','Sirf tab deny jab request management se aaye, kyunki SCPs sirf management identities par asar daalte hain'],0,'Child/identity grants missing ancestor limit ko chauda nahi kar sakte. FullAWSAccess identity grant nahi; member identities par asar hota hai jabki management identities chhooti hain.'),
    Q('Root par ek Deny lagta hai aur ek child OU par usi action ka Allow hai. Kya hoga?', 'Member identity ke liye lagu saaf Deny jeetta hai; child Allow upar se aayi rok ko override nahi kar sakta',['Child Allow jeetta hai, kyunki organization policies local config merge jaisa "aakhri file jeete" order use karti hain','Account admin AdministratorAccess laga kar Deny bypass kar sakta hai, kyunki identity grants ki priority limits se zyada hai','Wahi role delegated-administrator member mein le jaane se us role par se saare SCP restrictions apne aap hat jaate hain'],1,'Raaste mein lagu saaf Deny jeetta hai. Koi file order ya IAM admin grant ise override nahi karta; delegated membership bhi SCP ke andar rehti hai.'),
    Q('Kaun SCP ki rok se bahar hai, par phir bhi sahi service/IAM authority maangta hai?', 'Management account ki identities aur service-linked roles; delegated member identities aam taur par scope mein rehti hain',['Har role jiske naam mein service hai, kyunki aam application execution roles aur service-linked roles ek hi hain','Har account jiska naam audit hai, kyunki account ka display naam member ko management ki ownership de deta hai','Har member root user, kyunki SCPs sirf non-root IAM users ko chhoote hain aur member account ke root ko kabhi limit nahi kar sakte'],2,'SCP ke exceptions khaas hain. Aam service/execution role zaroori nahi ki service-linked role ho; naam ownership nahi badalte; member root SCP ke scope mein hai.'),
    Q('Scoped Region SCP maanga endpoint allow karta hai. Kya isse har jagah saabit hota hai ki saara data usi Region mein rehta hai?', 'Nahi; RequestedRegion request ka endpoint control karta hai, aur service ki khaas jagah/destination ka context review karna padta hai',['Haan, kyunki har AWS API saara result data usi Region mein rakhti hai jahan signed request ka endpoint hai','S3CreateBucket ke liye haan, kyunki endpoint Region allowed ho toh diya gaya LocationConstraint ignore hota hai','Sirf management identities ke liye nahi, kyunki member roles alag destination field wali API kabhi chala hi nahi sakte'],3,'Endpoint aur aage ka data kahan rakha jaata hai, alag hain. S3LocationConstraint aur doosri APIs jaisa service ka context review karo; na member status na endpoint ki permission har jagah residency ka saboot hai.'),
    Q('Ek central portal se kai AWS accounts mein employees ka scoped access chahiye. Kya chunoge?', 'IAM Identity Center organization-instance ke assignments/permission-set role workflow, review kiye grants aur limits ke saath',['Akela SCP Allow, kyunki permission ki limits employees ke sessions dete hain aur saare zaroori account roles banate hain','Identity Center account instance, kyunki alag application instances apne aap kai accounts ka AWS access de dete hain','Sirf RAM, kyunki subnet share karne se poori employee directory aur permission-set assignments bhi ban jaate hain'],0,'Organization-instance wala employee workflow assign kiya account access deta hai; limits phir bhi lagti hain. SCPs sessions nahi dete, account instances ka scope alag hai, aur RAM supported resources share karta hai, employee identity ki jagah nahi leta.'),
    Q('Config delegated administrator register hua. Readiness review ko aur kya check karna chahiye?', 'Exact trusted-access/service integration aur zaroori Config runtime setup; registration member ko SCPs se chhoot nahi deta',['Kya delegate management account ban gaya, kyunki har service registration organization ki ownership transfer karta hai','Aur kuch nahi, kyunki Organizations registration har jagah saare Config recorders, rules aur aggregators apne aap deploy kar deta hai','Sirf account ka naam, kyunki audit label har supported security service ko wahi delegated taakat de deta hai'],1,'Delegation ek service ka metadata/zarooratein hai, poori service ka deploy ya management ownership nahi. Member ki limits rehti hain; labels doosre integrations set nahi karte.'),
    Q('Basic tag-policy value/case enforcement on hai. Missing tag ke saath create rokna hai. Sahi agla kadam?', 'Required-key/IaC/reporting coverage aur supported request-tag IAM/SCP guards review karo; basic value rules missing tags nahi rokte',['Maan lo basic tag-value enforcement har AWS service mein har bina tag wale resource ko apne aap reject karta hai','Account ke IAM grants ki jagah tag policy lagao, kyunki tag consistency policies har zaroori resource permission deti hain','Resource inventory band karo, kyunki compliance reports mein woh har resource pehle se hai jispe kabhi user-defined tag nahi laga'],2,'Basic rules missing keys cover nahi karte; aaj ke Required-key/IaC/reporting features ka supported scope/dikhne ki limits hain. Jahan supported ho wahan likhe create/request-tag controls use karo; tag policies grant ya har jagah ki inventory nahi.'),
    Q('Aaj ka SCP syntax reference Allow ke saath Condition/Resource allow karta hai. Ek purana guide dono mana karta hai. Kaun jeetega?', 'Aaj ka SCP syntax aur test kiye supported niyam use karo; 2025 ke expansion ne yeh taakat jodi, jabki local simulators chhote ho sakte hain',['Purana niyam follow karo, kyunki AWS service launch ke baad apni permission policy ki language kabhi nahi badha sakti','Resource wale SCP Allow ko naya IAM grant maano, kyunki flexible syntax grant aur limit ka farak mita deta hai','Maan lo simulator ki har unsupported expression chupchaap chalti hai, kyunki AWS ki aaj ki taakat local code mein apne aap aa jaati hai'],3,'Aaj ke primary syntax/launch docs purani rok ko badal dete hain; syntax badhne se SCP grant nahi ban jaata. Limit wale simulator ko unsupported scope batana chahiye, chupchaap poore AWS support ka daava nahi.')
   ]}
  ],
  interview:{title:'Interview: alag rakhna, grants aur toota Allow raasta',instructions:'Chaar faisle, phir sirf bataye ancestor/policy ki galtiyan theek karo, pehle se bane Sandbox aur service registry bachate hue.',questions:[
   Q('Prod/dev ke alag accounts hain, par ek shared dev credential chaude production roles assume kar sakta hai. Sabse achha jawaab?', 'Cross-account trust/grants aur credentials ki handling review karke kam karo; sirf account ka alag hona poora bachav nahi',['Account boundary ko kaafi maano, kyunki credentials ko do AWS accounts ke paar kabhi permission nahi mil sakti','Saare resources wapas ek account mein le aao, kyunki cross-account trust saabit karta hai ki alag accounts ka koi fayda nahi','Role trust ki jagah SCP Allow lagao, kyunki organization ki limits hi thodi der ke production sessions deti hain'],0,'Accounts alag rakhte hain, par allowed credentials/trust boundaries paar kar sakte hain. Asli raaste kam karo; na alag rakhna chhodna, na SCP Allow chaudi session authority ko theek karta hai.'),
    Q('Same-account bucket policy role ARN ko PutObject deti hai; IAM mein Allow nahi, boundary allow karti hai aur SCP raasta allow karta hai. Faisla?', 'Woh role-ARN resource grant object request allow kar sakta hai; yeh bina resource policy ke bucket banane se alag hai',['Deny, kyunki resource policies kabhi bhi role ko usi action ke matching identity Allow ke bina permission nahi de sakti','Allow, chahe role ki boundary action allow na kare, kyunki har resource grant saari boundary aur SCP limits bypass karta hai','Har naya bucket banana bhi allow, kyunki pehle se bane object ka grant aage ke saare S3 resources par apne aap lag jaata hai'],1,'Same-account role-ARN resource grants asli grants hain, lagu boundary/limits ke andar. Yeh har jagah restrictions bypass nahi karte, na aage banne wale buckets ko permission dete hain; user/session ARN raaston ke niyam alag hain.'),
    Q('Control Tower proactive controls on hain. Ek seedhi Terraform AWS-provider API resource banati hai. Kya hook ka check maan sakte hain?', 'Nahi; asli provisioning raasta aur coverage check karo, kyunki proactive controls supported CloudFormation hook operations ke liye hain',['Haan, kyunki Control Tower ka koi bhi control Terraform se chalane par har seedhi provider API CloudFormation stack operation ban jaati hai','Haan, kyunki detective Config rule target service ke resource banane se pehle hamesha synchronously request rok deta hai','Sirf tab nahi jab SCP action grant kare, kyunki SCP Allow hi woh mechanism hai jo har CloudFormation hook band karta hai'],2,'Proactive hooks ka khaas provisioning coverage hai. Controls ko Terraform se chalana seedhi APIs ko nahi badalta; Config ka pakadna synchronous rokne se alag hai, aur SCP Allow na access deta hai na hooks band karta hai.'),
    Q('RI/Savings Plans discount sharing accounts mein set hai. Kya sahi hai?', 'Eligible faydon ka batna khareedne wale/account/group ki preferences par chalta hai; yeh IAM access ya chalti capacity ki guarantee nahi',['Har account ko fixed extra discount milta hai, commitment ka use, sharing preferences aur fayde ki eligibility kuch bhi ho','Shared discount ek cross-account role trust grant bhi hai, isliye use karne wale apne aap khareedne wale workload ka access paa lete hain','Saare resource quotas aur capacity reservations ek bina limit pool ban jaate hain, kyunki ek invoice permission aur infrastructure dono jod deta hai'],3,'Billing preferences/eligibility fayde tay karti hain, aaj ke group modes samet. Discounts IAM grants, fixed har jagah ki bachat, bina limit quotas ya chalti capacity ki guarantee nahi.') ,
    {terminal:{type:'terminal',title:'🖥️ Ancestor Allow wapas lao aur Region condition theek karo',instructions:'Purana Sandbox, accounts, delegation aur production ka kaam bache rehne chahiye. Policy types band mat karo, na policy ki pehchaan badlo.',goal:'<p>Workloads '+W+' par sirf Deny wala baseline hai, koi lagu Allow nahi; p-region01 mein ulta StringEquals hai. Pehle se bana p-FullAWSAccess Workloads par lagao, region.json se asli p-region01 ka content update karo, phir poora describe-policy. Theek hua Content aana chahiye, saath mein ghar ka CreateBucket/object allow aur galat endpoint/location/StopLogging deny. Purana Sandbox bachao: '+SAND+', saare accounts/production ka kaam, audit delegation/trusted access aur p-notrail1. 3 actions; aaj ka policy revision/read zaroori.</p>',account:seed(true,true),files,tasks:itasks,solution:isolution,hints:['Child/IAM Allow ancestor ki kami theek nahi kar sakta. Deny + Equals apne ghar ka endpoint bhi rokta hai; dono alag galtiyan theek karo.',isolution.slice(0,2).join(' phir '),isolution[2]],success:AG.allOf(itasks),successText:'Purana Sandbox/kaam/registry bacha. Workloads Allow aur review ki Region/location condition wapas aayi; aaj ka policy content aur limit wale request results match karte hain. Asli AWS enforcement ek alag approved canary test hai.'}}
  ]},
  success:['Account/OU design ko trust, ownership aur policy scope se samjha sakta hoon.','SCP raasta, saaf Deny aur bataye IAM/resource grant raaste mein faisla karne wali layer pehchaan sakta hoon.','Identity Center/Control Tower/RAM/delegation aur aaj ke policy types chun kar limits check kar sakta hoon.'],
  homework:'<p>Optional, sirf approved alag organization/member-account canary. Asli account banana, band karna, poore root par SCP badlav ya policy type band karna, sabke liye alag saaf manzoori aur recovery/billing ki planning chahiye. Read-only se shuru karo: root/parents/seedhi policies, aaj ki State aur asli grants/context ki list banao. Lagane se pehle chhoti proposed policy aur rollback/exception ka owner review karo. Manzoori ke saath sahi positive/negative AWS requests aur service setup check karo, production aur audit ka saboot bachate hue. Membership hatana account band karna nahi; sirf apne test resources saaf karo aur chalu charges/retention ki zimmedariyan check karo.</p>',
  cards:[{front:'Account boundary enough?',back:'Mazboot alag rakhna, par chaude cross-account trust/credentials ya shared dependencies se poora bachav nahi. Ownership alag rakho aur access ke asli raaste kam karo.'},{front:'SCP path rule?',back:'Root/har OU/account par lagu Allow; ek level par kai policies Allow jodti hain; koi bhi lagu saaf Deny jeetta hai. SCP kabhi grant nahi deta.'},{front:'SCP exceptions?',back:'Management identities aur service-linked roles chhoote hain; delegated member identities aur member root aam taur par scope mein. Chhoot manmaani grant nahi.'},{front:'Resource grant vs identity grant?',back:'Same-account role-ARN resource grant identity Allow ke bina object access de sakta hai, par boundary/session ki limit ke andar. Seedhe user/session/wildcard Principal raaste alag hain; SCP phir bhi maayne rakhta hai.'},{front:'Region endpoint vs data ki jagah?',back:'RequestedRegion request ka endpoint hai. S3LocationConstraint jaisa service ka khaas location/destination context review karo; har global service ko todne se bacho.'},{front:'Identity Center / Account Factory / RAM?',back:'Employees ka account/application access; baar-baar ek jaisa account baseline; supported resource sharing. Alag goals, grants aur zarooratein.'},{front:'Aaj ki policy/billing ki shartein?',back:'SCP ka 2025 poora syntax; RCP/declarative/tag/backup ka coverage alag. Basic tag rules missing tags laagu nahi karte; aaj ka required-key/IaC scope maayne rakhta hai. Eligible discount sharing permission/capacity nahi.'},{front:'Lab22 evidence?',back:'Virtual organization/tree/attachments/delegation/identity pass hue; Moto missing trusted access aur mana kiya member bucket maan leta hai. Asli AWS permission/account band karna ya service runtime ka saboot nahi.'}]
 }]);
})();
